var e=class{storage;constructor(e){this.storage=e}async listConversationDocuments(){let e=this.storage.listFiles().filter(e=>e.path.startsWith(`Conversations/`)&&e.path.toLocaleLowerCase(`en-US`).endsWith(`.md`));return Promise.all(e.map(async e=>{let t=await this.storage.readFile(e.id);return{id:t.id,path:t.path,content:t.content,modifiedAt:t.modifiedAt}}))}async writeConversation(e){if(e.id){let t=this.storage.listFiles().find(t=>t.id===e.id);if(!t)throw Error(`Conversation file no longer exists`);t.path!==e.path&&await this.storage.renameFile(e.id,e.path);let n=await this.storage.writeFile(e.id,e.content);return{id:n.id,path:n.path,content:n.content,modifiedAt:n.modifiedAt}}let t=await this.storage.createFile(e.path,e.content);return{id:t.id,path:t.path,content:t.content,modifiedAt:t.modifiedAt}}async removeConversation(e){await this.storage.deleteFile(e)}async writeAttachment(e,t){if(!e.bytes)throw Error(`Attachment bytes are unavailable`);await this.storage.writeAttachment({path:t,bytes:e.bytes,mimeType:e.mimeType,contentDigest:e.digest})}async attachmentExists(e){return this.storage.listAllFiles().some(t=>t.path===e&&t.kind===`attachment`)}async removeAttachment(e){let t=this.storage.listAllFiles().find(t=>t.path===e&&t.kind===`attachment`);t&&await this.storage.deleteFile(t.id)}async saveUndoTransaction(e){await this.storage.writeLocalRecord(`conversation-undo`,e.id,e,e.expiresAt)}async loadUndoTransaction(e){return this.storage.readLocalRecord(`conversation-undo`,e)}async removeUndoTransaction(e){await this.storage.deleteLocalRecord(`conversation-undo`,e)}};export{e as VaultConversationWorkspace};